// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address attacker, uint256 value) public {
        vm.assume(attacker != address(this));
        value = bound(value, 1, 1 ether);

        vm.deal(address(this), 2 ether);
        (bool sent,) = address(c).call{value: value}('');
        require(sent);

        RecvHelper helper = new RecvHelper();

        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        try c.sendMoney(address(helper), value, "") {
        } catch {
        }

        assertTrue(address(c).balance >= 1 wei);
    }
}

contract RecvHelper {
    receive() external payable {}
}
